(5023, '2026-05-18 04:15:39', '2026-05-18 04:15:39', '5101', '[{\"id\":1779077629935,\"title\":\"President’s NBEMS Gold Medal in DrNB Endocrinology\",\"description\":\"Received the prestigious President’s NBEMS Gold Medal in DrNB Endocrinology for outstanding academic performance and excellence in super speciality medical education.\",\"date\":\"2022-05-18\"},{\"id\":1779077676464,\"title\":\"AIR 25 – NBE Super Speciality Entrance Exam\",\"description\":\"Secured All India Rank 25 in the National Board of Examinations (NBE) Super Speciality Entrance Examination.\",\"date\":\"2018-03-18\"},{\"id\":1779077708543,\"title\":\"AIR 130 – NBE DNB PG Entrance Exam\",\"description\":\"Secured All India Rank 130 in the National Board of Examinations (NBE) DNB Post-Graduation Entrance Examination\",\"date\":\"2013-11-18\"}]', '[]'),
(5024, '2026-05-18 05:49:28', '2026-05-18 05:49:28', '5103', '[{\"id\":1779083323665,\"title\":\"Research Grant Award – Endocrine Society of India\",\"description\":\"Received a research grant award of Rs. 2,00,000 from the Endocrine Society of India for the research proposal titled “Serum Fibroblast Growth Factor 21 (FGF21) Levels in Patients with Hyperthyroidism and its Association with Body Fat Percentage\",\"date\":\"2017-05-18\"},{\"id\":1779083370128,\"title\":\"Third Place – KRSSDI Quiz Competition\",\"description\":\"Secured third place in the Quiz Competition conducted by KRSSDI Mangalore for excellence in diabetology and clinical medical knowledge.\",\"date\":\"2014-05-18\"}]', '[]'),
(5025, '2026-05-18 06:40:48', '2026-05-18 06:40:48', '5105', '[{\"id\":1779086334785,\"title\":\"APJ Abdul Kalam Excellency Award\",\"description\":\"Received the prestigious APJ Abdul Kalam Excellency Award from Megacity Nava Kala Vedika for outstanding contribution and excellence in the field of Plastic & Cosmetic Surgery.\",\"date\":\"2018-09-18\"},{\"id\":1779086388880,\"title\":\"Best Faculty Paper Presentation – APRAS\",\"description\":\"Awarded Best Faculty Paper Presentation at APRAS (Andhra Pradesh & Telangana) for academic contribution and excellence in reconstructive plastic surgery research.\",\"date\":\"2017-05-18\"},{\"id\":1779086421225,\"title\":\"MBBS Gold Medalist\",\"description\":\"Completed MBBS as a Gold Medalist from MKCG Medical College, Berhampur, Orissa, demonstrating academic excellence in medical education.\",\"date\":\"2000-05-18\"}]', '[]'),
(5026, '2026-05-18 07:20:16', '2026-05-18 07:20:16', '5106', '[{\"id\":1779088721922,\"title\":\"Winner – 2nd Annual Lung Masterclass Quiz\",\"description\":\"Won the prestigious Lung Masterclass Quiz competition held in Mumbai demonstrating excellence in thoracic oncology and clinical oncology knowledge.\",\"date\":\"2019-05-18\"},{\"id\":1779088750787,\"title\":\"Winner – Institutional Quiz on Lung Cancer\",\"description\":\"Secured first place in Institutional Quiz on Lung Cancer conducted at Gujarat Cancer & Research Institute, Ahmedabad.\",\"date\":\"2019-02-18\"},{\"id\":1779088780114,\"title\":\"Winner – City Level Quiz on Breast Cancer\",\"description\":\"\\nWon City Level Breast Cancer Quiz competition for excellence in oncology academics and clinical knowledge.\",\"date\":\"2019-05-18\"}]', '[]'),
(5027, '2026-05-18 09:07:21', '2026-05-18 09:07:21', '5107', '[{\"id\":1779095176516,\"title\":\": Organising Committee Member – HAIRCON 2017\",\"description\":\"Served as Organising Committee Member for HAIRCON 2017 conducted by the Association of Hair Restoration Surgeons, India, contributing to academic and scientific hair restoration education programs.\",\"date\":\"2017-05-18\"},{\"id\":1779095243972,\"title\":\"Scientific Committee Member – HAIRCON 2017\",\"description\":\"Appointed as Scientific Committee Member for HAIRCON 2017 organized by the Association of Hair Restoration Surgeons, India.\",\"date\":\"2017-05-18\"},{\"id\":1779095263239,\"title\":\"Faculty Speaker – Facial Aesthetic Training & Education (F.A.T.E.)\",\"description\":\"Invited as Faculty Speaker for Facial Aesthetic Training & Education (F.A.T.E.) program focusing on aesthetic dermatology and facial cosmetic procedures.\",\"date\":\"2017-07-18\"},{\"id\":1779095286180,\"title\":\"2nd Prize – Poster Presentation\",\"description\":\"Received 2nd prize in Poster Presentation for the research poster titled “Coexistence of Lipedematous Scalp with Alopecia Areata” at Dermatology and Allied Specialities Summit\",\"date\":\"2014-08-18\"},{\"id\":1779095308791,\"title\":\"Interstate Leprosy Quiz Award\",\"description\":\"Secured 3rd prize in Interstate Leprosy Quiz held at All India Institute of Medical Sciences (AIIMS), New Delhi, India.\",\"date\":\"2014-03-18\"}]', '[]'),
(5028, '2026-05-18 09:31:20', '2026-05-18 09:31:20', '5109', '[{\"id\":1779096660962,\"title\":\"Excellence in Medical Oncology\",\"description\":\"Recognized for outstanding contributions in cancer care, chemotherapy, and patient-centered oncology treatment\",\"date\":\"2023-05-18\"},{\"id\":1779096694163,\"title\":\"Patient Choice Award\",\"description\":\"Recognized by patients for compassionate cancer care and exceptional oncology treatment services.\",\"date\":\"2022-05-18\"}]', '[]'),
(5029, '2026-05-18 09:49:18', '2026-05-18 09:49:18', '5110', '[{\"id\":1779097691529,\"title\":\"Best Surgical Video Award\",\"description\":\"Received Best Surgical Video Award for “Elimination of Dog Ears Anastomosis by Invagination of Rectal Stump in Minimally Invasive Colorectal Surgery\",\"date\":\"2023-05-18\"},{\"id\":1779097709047,\"title\":\"First Prize – IASO Mid-Term Conference Paper Presentation\",\"description\":\"Won first prize for paper presentation at the Mid-Term Conference of the Indian Association of Surgical Oncology (IASO) held at Mount Abu.\",\"date\":\"2019-03-18\"},{\"id\":1779097734393,\"title\":\"First Prize – Post Graduate Oncology Quiz Contest\",\"description\":\"Won first prize in Post Graduate Oncology Quiz Contest held in Ahmedabad.\",\"date\":\"2020-05-18\"}]', '[]');
