(4907, '3564', '[{\"id\":1748240219371,\"institute_name\":\" Rangaraya Medical College, Kakinada \",\"degree_title\":\"MBBS\",\"start_date\":\"0001-05-26\",\"ending_date\":\"1978-01-01\",\"degree_description\":\"MBBS: Rangaraya Medical College, Kakinada (Graduated in 1978)\"}]', '[{\"id\":1748240303917,\"company_name\":\" Padmaja Nursing Home\",\"job_title\":\"General Physician\",\"start_date\":\"1978-05-26\",\"ending_date\":\"\",\"job_description\":\" Services Offered\\nDr. Rao provides a range of medical services, including:\\n\\nPreventive Medicine\\n\\nDiabetes Management\\n\\nGeneral Health Checkups\\n\\nInfectious Disease Treatment\\n\\nFever Treatment\\n\\nSkin Checks\\n\\nObstetrics-related Consultations\\n\\nInsomnia Treatment\"}]', '2025-05-26 06:20:20', '2025-05-26 06:20:20'),
