(5223, '4964', '[{\"id\":1752909400250,\"institute_name\":\"Bangalore Medical College, Bangalore\",\"degree_title\":\"MBBS\",\"start_date\":\"1986-09-01\",\"ending_date\":\"1991-05-01\",\"degree_description\":\"MBBS, Bangalore Medical College, Bangalore (graduated circa 1991)\"},{\"id\":1752909438476,\"institute_name\":\"Grant Medical College\",\"degree_title\":\"MS (General Surgery)\",\"start_date\":\"1991-09-01\",\"ending_date\":\"1994-05-01\",\"degree_description\":\"MS (General Surgery), Grant Medical College & Sir JJ Hospital, Mumbai (1994; secured First Rank in University of Bombay)\"},{\"id\":1752909438724,\"institute_name\":\"National Board of Examinations, New Delhi\",\"degree_title\":\"DNB (General Surgery / Gastroenterology)\",\"start_date\":\"1991-09-01\",\"ending_date\":\"1994-05-01\",\"degree_description\":\"DNB (General Surgery / Gastroenterology), National Board of Examinations, New Delhi (1994)\\n\\nFRCS (General Surgery), Royal College of Physicians and Surgeons, Glasgow (1996)\\n\\nAdvanced training: European Institute of Tele‑Surgery (EITS), Strasbourg (laparoscopy) and National University Hospital, Singapore (bariatric & metabolic surgery) \"}]', '[{\"id\":1752909307522,\"company_name\":\"Apollo Hospitals\",\"job_title\":\"Director & Senior Consultant, Department of Minimal Access, GI & Bariatric/Metabolic Surgery\",\"start_date\":\"1998-01-01\",\"ending_date\":\"\",\"job_description\":\"Professional Experience\\n\\n27+ years of clinical practice in Minimal Access, Gastrointestinal, Bariatric, Robotic, SILS, and Thoracoscopic surgeries \\n\\n\\nPast roles include Lead Consultant at Fortis Hospitals (Bangalore) and Aster RV Hospital \\n\\n\\nCurrent: Director & Senior Consultant, Department of Minimal Access, GI & Bariatric/Metabolic Surgery at Apollo Hospitals (Jayanagar and Sheshadripuram branches), Bengaluru \\n\\n\\nVisiting laparoscopic surgeon at hospitals in Mauritius, Uganda, Iraq, Ethiopia; faculty at national-level surgical conferences;