(5242, '4984', '[{\"id\":1753094881058,\"institute_name\":\"University College of Medical Sciences\",\"degree_title\":\"MBBS\",\"start_date\":\"1996-09-01\",\"ending_date\":\"2001-09-01\",\"degree_description\":\"MBBS – University College of Medical Sciences (UCMS), Delhi University (2001) \"},{\"id\":1753094918473,\"institute_name\":\"Maulana Azad Medical College, New Delhi \",\"degree_title\":\"MD (Medicine)\",\"start_date\":\"2003-09-01\",\"ending_date\":\"2006-05-01\",\"degree_description\":\"MD (Medicine) – Maulana Azad Medical College, New Delhi (2006) \"},{\"id\":1753094946857,\"institute_name\":\"G.B. Pant Hospital/Maulana Azad Medical College, New Delhi \",\"degree_title\":\"DM (Gastroenterology) \",\"start_date\":\"2008-09-01\",\"ending_date\":\"2011-05-01\",\"degree_description\":\"DM (Gastroenterology) – G.B. Pant Hospital/Maulana Azad Medical College, New Delhi (2011)\"}]', '[{\"id\":1753094847253,\"company_name\":\" Indraprastha Apollo Hospital,\",\"job_title\":\"Consultant Gastroenterologist \",\"start_date\":\"2014-01-01\",\"ending_date\":\"\",\"job_description\":\"Experience & Clinical Expertise\\n\\nOver 14–16 years of experience in gastroenterology and hepatology; some sources cite 23 years \\n\\nConsultant Gastroenterologist at Indraprastha Apollo Hospital, Sarita Vihar, New Delhi (also practices at Apollo Noida and Gastro & Endo Care Clinic, Noida)\"}]', '2025-07-21 10:49:38', '2025-07-21 10:49:38');
