(5243, '4985', '[{\"id\":1753096004223,\"institute_name\":\"Rajiv Gandhi Medical College, Maharashtra University of Health Sciences, Nashik\",\"degree_title\":\"MBBS\",\"start_date\":\"2002-09-01\",\"ending_date\":\"2008-05-01\",\"degree_description\":\"MBBS – Rajiv Gandhi Medical College, Maharashtra University of Health Sciences, Nashik (2002–2008)\"},{\"id\":1753096058440,\"institute_name\":\" P.D. Hinduja National Hospital\",\"degree_title\":\"DNB (General Medicine) \",\"start_date\":\"2010-09-01\",\"ending_date\":\"2013-05-01\",\"degree_description\":\"DNB (General Medicine) – P.D. Hinduja National Hospital, Mumbai (2010–2013) \\n\"},{\"id\":1753096058667,\"institute_name\":\"Bombay Hospital Institute of Medical Sciences, Mumbai \",\"degree_title\":\"DNB (Gastroenterology)\",\"start_date\":\"2014-09-01\",\"ending_date\":\"2017-05-01\",\"degree_description\":\"DNB (Gastroenterology) – Bombay Hospital Institute of Medical Sciences, Mumbai (2014–2017)\"}]', '[{\"id\":1753095912994,\"company_name\":\"Apollo Hospitals\",\"job_title\":\"Consultant, Gastroenterology, Hepatology & Liver Transplantation\",\"start_date\":\"2019-01-01\",\"ending_date\":\"\",\"job_description\":\"Consultant, Gastroenterology, Hepatology & Liver Transplantation, Apollo Hospitals, Navi Mumbai (since Jul 2019) \\n\\n\\nPreviously Associate Consultant at Apollo Navi Mumbai (Jul 2018–Jul 2019) \"}]', '2025-07-21 11:08:58', '2025-07-21 11:08:58'),
(5244, '4986', '[{\"id\":1753100019731,\"institute_name\":\"\",\"degree_title\":\"MBBS, MD (Internal Medicine), DNB (Gastroenterology) \",\"start_date\":\"0001-01-01\",\"ending_date\":\"0001-01-01\",\"degree_description\":\"MBBS, MD (Internal Medicine), DNB (Gastroenterology) \"}]', '[{\"id\":1753099969721,\"company_name\":\"Apollo Hospitals, Navi Mumbai\",\"job_title\":\"Consultant in Gastroenterology & Hepatology\",\"start_date\":\"2017-01-01\",\"ending_date\":\"\",\"job_description\":\" Experience & Professional \\n\\n\\nOver 13–16 years of experience in gastroenterology/hepatology \\n\\n\\nCareer history:\\n\\nAssistant Professor, KEM Hospital (2013–2016)\\n\\nAssociate Professor, Seth GS Medical College & KEM (2016–2019)\\n\\nClinical Head, IBD Clinic at KEM Hospital\\n\\nPG guide for DM/DNB students since 2019\\n\\nSenior Consultant & PG guide, Apollo Hospitals since May 2019\\n\\nGeneral Secretary, Gastroenterology Research Society, Mumbai (since 2020)\"}]', '2025-07-21 12:14:04', '2025-07-21 12:14:04'),
(5245, '4987', '[{\"id\":1753100856384,\"institute_name\":\"Jiwaji University, Gwalior\",\"degree_title\":\"MBBS\",\"start_date\":\"1991-09-01\",\"ending_date\":\"1996-05-01\",\"degree_description\":\"MBBS, Jiwaji University, Gwalior (1991–1996)\"},{\"id\":1753100901408,\"institute_name\":\"G.R. Medical College, Gwalior\",\"degree_title\":\"MD (General Medicine)\",\"start_date\":\"1998-09-01\",\"ending_date\":\"2001-05-01\",\"degree_description\":\"MD (General Medicine), G.R. Medical College, Gwalior (1998–2001) \\n\"},{\"id\":1753100901588,\"institute_name\":\"Banaras Hindu University\",\"degree_title\":\"DM (Gastroenterology)\",\"start_date\":\"2004-09-01\",\"ending_date\":\"2007-05-01\",\"degree_description\":\"DM (Gastroenterology), Banaras Hindu University, Varanasi (2004–2007)\"}]', '[{\"id\":1753100801711,\"company_name\":\"Apollo Hospitals\",\"job_title\":\"Consultant in Medical Gastroenterology & Hepatology\",\"start_date\":\"2011-01-01\",\"ending_date\":\"\",\"job_description\":\"Experience & Clinical Expertise\\n\\nOver 16–18 years of experience, including 15+ years as a specialist \\n\\nCurrently Consultant at:\\n\\nApollo Hospitals, CBD Belapur (Navi Mumbai)\\n\\nGastro World – Dr. Vashistha’s Liver & Gut Clinic, Powai\\n\\nDr. L. H. Hiranandani Hospital, Powai\\n\\nNanavati Hospital, Vile Parle \\nHiranandani Hospital\\n\\n\\nFormer Consultant roles at Kokilaben Dhirubhai Ambani Hospital, Fortis Mulund, Fortis Raheja, Upasani Super Speciality Hospital, and Nanavati/Max \"}]', '2025-07-21 12:29:16', '2025-07-21 12:29:16'),
(5246, '4988', '[{\"id\":1753101650199,\"institute_name\":\"MGM Institute of Health Sciences, Navi Mumbai\",\"degree_title\":\"MBBS\",\"start_date\":\"2004-09-01\",\"ending_date\":\"2009-05-01\",\"degree_description\":\"MBBS, MGM Institute of Health Sciences, Navi Mumbai (2009)\"},{\"id\":1753101650260,\"institute_name\":\"Rajawadi Hospital, Ghatkopar \",\"degree_title\":\"DNB – General Surgery\",\"start_date\":\"2010-09-01\",\"ending_date\":\"2013-05-01\",\"degree_description\":\"DNB – General Surgery, Rajawadi Hospital, Ghatkopar (2013)\\n\\nFellowship in Minimal Access Surgery (FMAS), World Laparoscopy Hospital, Gurgaon (2014) \\n\\n\\nFellowship in Advanced Gastrointestinal Endoscopy (FAGE), Maharashtra University of Health Sciences, Nashik (2018) \"}]', '[{\"id\":1753101609206,\"company_name\":\"Apollo Spectra Hospital\",\"job_title\":\" Surgical Gastroenterologist and Laparoscopic Surgeon\",\"start_date\":\"2013-01-01\",\"ending_date\":\"\",\"job_description\":\"Experience & Clinical Focus\\n\\nApproximately 12–13 years of experience as a general, laparoscopic, and GI surgeon \\n\\n\\nSpecializes in GI surgery, minimally invasive laparoscopic procedures, and advanced therapeutic endoscopy (including ERCP, colonoscopy, and upper GI endoscopy)\"}]', '2025-07-21 12:42:06', '2025-07-21 12:42:06'),
(5247, '4989', '[{\"id\":1753178883725,\"institute_name\":\" Lokmanya Tilak Municipal Medical College & General Hospital, Mumbai\",\"degree_title\":\"MBBS\",\"start_date\":\"1997-09-01\",\"ending_date\":\"2002-05-01\",\"degree_description\":\"MBBS – Lokmanya Tilak Municipal Medical College & General Hospital, Mumbai (graduated ~2002)\"},{\"id\":1753178949514,\"institute_name\":\"Lokmanya Tilak Municipal Medical College & General Hospital, Mumbai\",\"degree_title\":\"MD in Dermatology \",\"start_date\":\"2002-09-01\",\"ending_date\":\"2005-05-01\",\"degree_description\":\"MD in Dermatology – Lokmanya Tilak Municipal Medical College & General Hospital, Mumbai (completed ~2005) \\n\\nFellowship in Cosmetic Dermatology & Laser – National University Hospital, Singapore (2008), backed by the International Society of Dermatology\\n\\n\\nVisiting Fellowship – Cosmetic Dermatology & Skin‑Laser at Stanford University, California (circa 2010)\\n\\n\\nAdditional expert training: Thermage (Radiofrequency facelift) under Boris Kunsevitsky (Singapore), and Botox/fillers under Dr Susan Weinkle in Florida\"}]', '[{\"id\":1753178811755,\"company_name\":\"SL Raheja Fortis Hospital \",\"job_title\":\"Senior Consultant – Cosmetic Dermatology & Lasers\",\"start_date\":\"2009-01-01\",\"ending_date\":\"\",\"job_description\":\"Experience & Positions\\n\\nOver 22 years in dermatology, including cosmetic, clinical dermatology, lasers, dermatosurgery, and dermatologic phototherapy \\n\\n\\nSenior Consultant – Cosmetic Dermatology & Lasers at SL Raheja Fortis Hospital (Mahim, Mumbai) \\n\\nCo‑Founder & Director of The Esthetic Clinics since 2009, originally started at Apollo Health City, Hyderabad, then expanded to Mumbai & other cities \\n\\n\\nFormer Head of Cosmetic Dermatology & Lasers at Apollo Health City, Hyderabad (2009–2011) \\n\\n\\nPrevious Consultant at Dr Rekha Sheth’s Skin & Hair Clinic, Mumbai (2006–2009\"}]', '2025-07-22 10:10:19', '2025-07-22 10:10:19'),
(5248, '4990', '[{\"id\":1753179658762,\"institute_name\":\"Maharashtra University of Health Sciences, Nashik,\",\"degree_title\":\"MBBS\",\"start_date\":\"2000-09-01\",\"ending_date\":\"2005-05-01\",\"degree_description\":\"MBBS – Maharashtra University of Health Sciences, Nashik, 2005 \\n\"},{\"id\":1753179695929,\"institute_name\":\"B.Y.L. Nair Hospital & T.N. Medical College, Mumbai\",\"degree_title\":\"MD in Dermatology\",\"start_date\":\"2008-09-01\",\"ending_date\":\"2009-05-01\",\"degree_description\":\"MD in Dermatology (or DVD/DDV) – B.Y.L. Nair Hospital & T.N. Medical College, Mumbai, 2008–2009\\n\\nDDV (Diploma in Dermatology, Venereology & Leprosy) – BYL Nair Hospital, Mumbai, 2009\"},{\"id\":1753179696196,\"institute_name\":\"Indian Board of Alternate Medicine\",\"degree_title\":\"MD in Alternative Medicine\",\"start_date\":\"2008-09-01\",\"ending_date\":\"2011-05-01\",\"degree_description\":\"MD in Alternative Medicine – Indian Board of Alternate Medicine, 2011\"}]', '[{\"id\":1753179593733,\"company_name\":\" Ambrosia Aesthetics, Andheri \",\"job_title\":\"Chief Dermatologist\",\"start_date\":\"2007-01-01\",\"ending_date\":\"\",\"job_description\":\"Experience & Positions\\n\\n19–20 years of experience overall, ~15 years as a specialist \\n\\n\\nFounded & Medical Director of:\\n\\nDr. Niketa\'s Skin Secrets (2011–2014)\\n\\nDr. Niketa\'s Advanced Dermatology Clinic (from 2014) \\n\\n\\nSenior Consultant / Clinic Head at Kaya Skin Clinic (2008–2012) \\n\\n\\nSenior Resident at BYL Nair Hospital (2006–2008) and Junior Resident at LTMGH Sion (2006) \\n\\n\\nCurrent Chief Dermatologist at Ambrosia Aesthetics, Andheri West, Mumbai; renowned as a celebrity dermatologist\"}]', '2025-07-22 10:23:02', '2025-07-22 10:23:02'),
(5249, '4991', '[{\"id\":1753180609046,\"institute_name\":\"University of Bombay\",\"degree_title\":\"MBBS\",\"start_date\":\"1981-09-01\",\"ending_date\":\"1986-05-01\",\"degree_description\":\"MBBS – University of Bombay, 1986.\\n\\n\"},{\"id\":1753180609101,\"institute_name\":\"University of Bombay\",\"degree_title\":\"Diploma in Dermatology (DDV/DVD) \",\"start_date\":\"1985-09-01\",\"ending_date\":\"1988-05-01\",\"degree_description\":\"Diploma in Dermatology (DDV/DVD) – University of Bombay, 1988.\\n\\n\"},{\"id\":1753180715268,\"institute_name\":\"Topiwala National Medical College & B.Y.L. Nair Charitable Hospital, Mumbai,\",\"degree_title\":\"MD in Dermatology\",\"start_date\":\"1987-09-01\",\"ending_date\":\"1990-05-01\",\"degree_description\":\"MD in Dermatology – Topiwala National Medical College & B.Y.L. Nair Charitable Hospital, Mumbai, 1990.\\n\\n\"},{\"id\":1753180715633,\"institute_name\":\" Dr. D.Y. Patil University, Navi Mumbai.\",\"degree_title\":\"PhD in Dermatology & Venereology\",\"start_date\":\"0001-01-01\",\"ending_date\":\"0001-01-01\",\"degree_description\":\"PhD in Dermatology & Venereology – Dr. D.Y. Patil University, Navi Mumbai.\\n\\nFRCP (Glasgow) – Fellow of the Royal College of Physicians and Surgeons, Glasgow.\\n\\nFAADV – Fellow of the American Academy of Dermatology.\"}]', '[{\"id\":1753180526152,\"company_name\":\"Apollo Hospitals (CBD Belapur)\",\"job_title\":\"dermatologist\",\"start_date\":\"2016-01-01\",\"ending_date\":\"\",\"job_description\":\"Experience & Positions\\n\\n35+ years of experience, with over 34 years as a dermatology specialist. \\n\\n\\nAssociate Professor of Dermatology, D.Y. Patil School of Medicine, Navi Mumbai (circa 2011–2015).\\n\\nClinical practice at Apollo Hospitals (CBD Belapur\"}]', '2025-07-22 10:36:43', '2025-07-22 10:36:43'),
(5250, '4992', '[{\"id\":1753181390077,\"institute_name\":\"University of Bombay\",\"degree_title\":\"MBBS\",\"start_date\":\"0001-01-01\",\"ending_date\":\"0001-01-01\",\"degree_description\":\"MBBS – University of Bombay\\n\"},{\"id\":1753181427686,\"institute_name\":\" Mumbai\",\"degree_title\":\"DVD (Diploma in Dermatology, Venereology & Leprosy) \",\"start_date\":\"0001-01-01\",\"ending_date\":\"0001-01-01\",\"degree_description\":\"DVD (Diploma in Dermatology, Venereology & Leprosy) – Mumbai\\n\"},{\"id\":1753181427923,\"institute_name\":\"Diplomate of National Board \",\"degree_title\":\"DNB in Dermatology \",\"start_date\":\"0001-01-01\",\"ending_date\":\"0001-01-01\",\"degree_description\":\"\\nDNB in Dermatology – Diplomate of National Board (Dermatology) level, reflecting post-graduate specialization \"}]', '[{\"id\":1753181336036,\"company_name\":\"Apollo Hospitals, Navi Mumbai \",\"job_title\":\"Chief Dermatologist\",\"start_date\":\"2003-01-01\",\"ending_date\":\"\",\"job_description\":\"Experience & Career Highlights\\n\\nOver 18 years of experience as a dermatologist, with clinical practice based at Apollo Hospitals, Navi Mumbai \\n\\n\\nFormer Chief Dermatologist at Skin Solutions (Vashi) for approximately 15 years; previously served as Project Chief Clinician at LTMMC Sion & CAPS (UCSF California initiative, 2002–2006) \"}]', '2025-07-22 10:51:37', '2025-07-22 10:51:37'),
(5251, '4994', '[{\"id\":1753182264461,\"institute_name\":\"University of Mumbai\",\"degree_title\":\"MBBS\",\"start_date\":\"1993-09-01\",\"ending_date\":\"1998-05-01\",\"degree_description\":\"MBBS, University of Mumbai (1998) \"},{\"id\":1753182327940,\"institute_name\":\"Lokmanya Tilak Municipal Medical College & Sion Hospital, Mumbai\",\"degree_title\":\"MD – Dermatology, Venereology & Leprosy\",\"start_date\":\"1999-09-01\",\"ending_date\":\"2002-05-01\",\"degree_description\":\"MD – Dermatology, Venereology & Leprosy, Lokmanya Tilak Municipal Medical College & Sion Hospital, Mumbai (2002) \"}]', '[{\"id\":1753182106867,\"company_name\":\"Apollo Hospitals \",\"job_title\":\"Dermatologist\",\"start_date\":\"2008-01-01\",\"ending_date\":\"\",\"job_description\":\"Experience & Career\\n\\nOver 17 years of experience treating various skin conditions, including pediatric dermatology, pigmentary disorders, psoriasis, and general clinical derm cases \\n\\n\\nPractices regularly at Apollo Hospitals (CBD Belapur)\"}]', '2025-07-22 11:06:11', '2025-07-22 11:06:11'),
