(5253, '4996', '[{\"id\":1753185534934,\"institute_name\":\" Terna Medical College, Mumbai \",\"degree_title\":\"MBBS\",\"start_date\":\"2004-09-01\",\"ending_date\":\"2009-05-01\",\"degree_description\":\"MBBS – Terna Medical College, Mumbai (2009) \\n\\n\\n\\n\"},{\"id\":1753185632394,\"institute_name\":\"DDV (Diploma in Dermatology & Venereology) \",\"degree_title\":\"DDV (Diploma in Dermatology & Venereology) \",\"start_date\":\"2011-09-01\",\"ending_date\":\"2014-05-01\",\"degree_description\":\"DDV (Diploma in Dermatology & Venereology) – Terna Medical College (2014) \"}]', '[{\"id\":1753185501468,\"company_name\":\"Apollo Spectra Hospitals\",\"job_title\":\"dermatologist\",\"start_date\":\"2011-01-01\",\"ending_date\":\"\",\"job_description\":\" Experience & Clinical Practice\\n\\n14–17 years of experience as a dermatologist, combining clinical care and cosmetic practice \\n\\n\\nPractices at Apollo Spectra Hospitals, Tardeo, Mumbai;\"}]', '2025-07-22 12:01:06', '2025-07-22 12:01:06'),
