(5299, '5114', '[{\"id\":1779103249008,\"institute_name\":\"Jaslok Hospital, Mumbai\",\"degree_title\":\"FSFN – Fellowship in Stereotactic & Functional Neurosurgery\",\"start_date\":\"2012-05-18\",\"ending_date\":\"2013-01-01\",\"degree_description\":\"Advanced fellowship training in functional neurosurgery, deep brain stimulation (DBS), epilepsy surgery, stereotactic procedures, and pain management.\"},{\"id\":1779103289136,\"institute_name\":\"Osmania Hospital, Hyderabad\",\"degree_title\":\"MCh Neurosurgery\",\"start_date\":\"2009-05-18\",\"ending_date\":\"2012-09-20\",\"degree_description\":\"Completed MCh Neurosurgery with specialized training in brain surgery, spine surgery, cerebrovascular surgery, trauma neurosurgery, hydrocephalus, congenital neurological disorders, and minimally invasive neurosurgical procedures.\"},{\"id\":1779103322576,\"institute_name\":\"Osmania Hospital, Hyderabad\",\"degree_title\":\"MS General Surgery\",\"start_date\":\"2006-05-18\",\"ending_date\":\"2009-03-02\",\"degree_description\":\"Completed MS General Surgery with extensive training in trauma surgery, gastrointestinal surgery, emergency surgical care, and operative management.\"},{\"id\":1779103368799,\"institute_name\":\"Kakatiya Medical College, Warangal\",\"degree_title\":\"MBBS\",\"start_date\":\"1999-05-18\",\"ending_date\":\"2005-09-12\",\"degree_description\":\"Completed MBBS with comprehensive medical training in medicine, surgery, pathology, neurology, and patient care\"}]', '[{\"id\":1779103393930,\"company_name\":\"Yashoda Hospitals\",\"job_title\":\"Senior Consultant Neurosurgeon\",\"start_date\":\"2020-05-18\",\"ending_date\":\"\",\"job_description\":\"Specializing in brain tumor surgery, spine surgery, cerebrovascular surgery, functional neurosurgery, epilepsy surgery, hydrocephalus treatment, and minimally invasive spine procedures.\"},{\"id\":1779103407832,\"company_name\":\"Aware Gleneagles Global Hospitals\",\"job_title\":\"Consultant Neurosurgeon\",\"start_date\":\"2018-05-18\",\"ending_date\":\"0020-12-11\",\"job_description\":\"Handled complex neurosurgical and spine cases including trauma neurosurgery, spinal disorders, and cerebrovascular surgeries.\\n\"},{\"id\":1779103408943,\"company_name\":\"Kamineni Hospitals\",\"job_title\":\"Consultant Neurosurgeon\",\"start_date\":\"2016-05-18\",\"ending_date\":\"2018-02-22\",\"job_description\":\"Managed advanced neurosurgical procedures, spine surgeries, pain management procedures, and neurological emergencies.\"},{\"id\":1779103410423,\"company_name\":\"CARE Hospital\",\"job_title\":\"Junior Consultant Neurosurgeon\",\"start_date\":\"2012-05-18\",\"ending_date\":\"2016-11-11\",\"job_description\":\"Worked in neurosurgical care involving trauma, spinal disorders, and minimally invasive neurosurgical procedures.\"}]', '2026-05-18 11:27:22', '2026-05-18 11:27:22'),
(5300, '5115', '[{\"id\":1779104113838,\"institute_name\":\"Nizam’s Institute of Medical Sciences (NIMS), Hyderabad\",\"degree_title\":\"DM Neurology\",\"start_date\":\"2006-05-18\",\"ending_date\":\"2009-09-12\",\"degree_description\":\"Completed DM Neurology with advanced training in stroke management, epilepsy, neurophysiology, movement disorders, headache disorders, neuropathies, and neurocritical care.\"},{\"id\":1779104151742,\"institute_name\":\"Osmania Medical College, Hyderabad\",\"degree_title\":\"MD General Medicine\",\"start_date\":\"2003-05-18\",\"ending_date\":\"2006-02-09\",\"degree_description\":\"Completed MD in General Medicine with extensive clinical training in internal medicine, neurology, emergency medicine, and complex neurological disorders.\"},{\"id\":1779104187174,\"institute_name\":\"Kakatiya Medical College, Warangal\",\"degree_title\":\"MBBS\",\"start_date\":\"1997-05-18\",\"ending_date\":\"2002-02-11\",\"degree_description\":\"Completed MBBS with comprehensive medical training in medicine, surgery, pathology, neurology, and patient care.\"}]', '[{\"id\":1779104219934,\"company_name\":\"Yashoda Hospitals, Somajiguda\",\"job_title\":\"Senior Consultant Neurologist\",\"start_date\":\"2019-05-18\",\"ending_date\":\"\",\"job_description\":\"Specializing in stroke treatment, epilepsy, headache disorders, Parkinson’s disease, neuropathies, movement disorders, neuroinfections, and advanced neurological care.\"},{\"id\":1779104264853,\"company_name\":\"Sunshine Hospitals\",\"job_title\":\"Consultant Neurologist\",\"start_date\":\"2014-05-18\",\"ending_date\":\"2018-02-09\",\"job_description\":\"Managed complex neurology cases involving stroke, epilepsy, movement disorders, headaches, neurocritical care, and neurophysiology services.\"},{\"id\":1779104314437,\"company_name\":\"Nizam’s Institute of Medical Sciences (NIMS)\",\"job_title\":\"Assistant Professor – Neurology\",\"start_date\":\"2009-05-18\",\"ending_date\":\"2014-02-12\",\"job_description\":\"Worked in academic neurology, neurophysiology, stroke care, epilepsy management, and postgraduate neurology training.\"}]', '2026-05-18 11:37:00', '2026-05-18 11:37:00'),
(5301, '5116', '[{\"id\":1779106276249,\"institute_name\":\"MKCG Medical College, Berhampur, Odisha\",\"degree_title\":\"MS Ophthalmology\",\"start_date\":\"2006-05-18\",\"ending_date\":\"2009-03-12\",\"degree_description\":\"Completed MS in Ophthalmology with advanced training in cataract surgery, LASIK procedures, glaucoma management, corneal diseases, and comprehensive eye care\"},{\"id\":1779106319136,\"institute_name\":\"MKCG Medical College, Berhampur, Odisha\",\"degree_title\":\"MBBS\",\"start_date\":\"1998-03-18\",\"ending_date\":\"2003-04-11\",\"degree_description\":\"Completed MBBS with comprehensive medical training in ophthalmology, medicine, surgery, pathology, and patient care.\"}]', '[{\"id\":1779106349192,\"company_name\":\"Iris Eye Hospital - Best Eye Care & Ophthalmology Clinic\",\"job_title\":\"Founder & Consultant Ophthalmologist\",\"start_date\":\"2016-05-18\",\"ending_date\":\"\",\"job_description\":\"Leading Iris Eye Hospital with specialization in cataract surgery, LASIK, glaucoma treatment, corneal disorders, refractive surgery, and advanced eye care procedures.\"},{\"id\":1779106380281,\"company_name\":\"Olive Hospital\",\"job_title\":\"Consultant Ophthalmologist\",\"start_date\":\"2012-05-18\",\"ending_date\":\"2015-01-11\",\"job_description\":\"Worked in comprehensive ophthalmology and cataract management before establishing Iris Eye Hospital.\"}]', '2026-05-18 12:13:34', '2026-05-18 12:13:34'),
(5302, '5117', '[{\"id\":1779107842556,\"institute_name\":\"Andhra Medical College, Visakhapatnam\",\"degree_title\":\"DM Gastroenterology\",\"start_date\":\"2010-05-18\",\"ending_date\":\"\",\"degree_description\":\"Completed DM in Gastroenterology with advanced training in liver diseases, pancreatitis, therapeutic endoscopy, ERCP, inflammatory bowel disease, and gastrointestinal disorders\"},{\"id\":1779107869556,\"institute_name\":\"Gandhi Medical College, Hyderabad\",\"degree_title\":\"MD General Medicine\",\"start_date\":\"2006-05-18\",\"ending_date\":\"2009-11-11\",\"degree_description\":\"Completed MD in General Medicine with extensive training in internal medicine, hepatology, critical care, and digestive diseases.\"},{\"id\":1779107913221,\"institute_name\":\"Kakatiya Medical College, Warangal\",\"degree_title\":\"\",\"start_date\":\"1999-05-18\",\"ending_date\":\"2005-01-11\",\"degree_description\":\"Completed MBBS with comprehensive clinical training in medicine, surgery, pathology, gastroenterology fundamentals, and patient care.\"}]', '[{\"id\":1779107950677,\"company_name\":\"Yashoda Hospitals, Malakpet\",\"job_title\":\"Senior Consultant Gastroenterologist\",\"start_date\":\"2020-05-18\",\"ending_date\":\"\",\"job_description\":\"Specializing in advanced gastroenterology, liver diseases, therapeutic endoscopy, ERCP, pancreatitis, GI bleeding, inflammatory bowel disease, and digestive disorders.\"},{\"id\":1779107978895,\"company_name\":\"CARE Hospitals\",\"job_title\":\"Consultant Gastroenterologist\",\"start_date\":\"2016-05-02\",\"ending_date\":\"2020-11-11\",\"job_description\":\"Managed complex gastrointestinal and hepatology cases including liver cirrhosis, pancreatic disorders, therapeutic endoscopy, and digestive tract diseases\"},{\"id\":1779108027732,\"company_name\":\"Asian Institute of Gastroenterology\",\"job_title\":\"Associate Consultant Gastroenterologist\",\"start_date\":\"2013-05-18\",\"ending_date\":\"2016-01-11\",\"job_description\"