INSERT INTO `feedbacks` (`id`, `created_at`, `updated_at`, `doctor_id`, `user_id`, `rating`, `comment`, `name`, `email`, `phone`) VALUES
(1, '2025-07-16 05:53:30', '2025-07-16 05:53:30', '4875', '4875', '5', 'Dr. Sandeep Thul is extremely professional and caring. He explained my condition in detail and made me feel very comfortable throughout the treatment. Highly recommend for anyone looking for expert care!', 'Ravindra Malle', 'malleravindra0465@gmail.com', '9705656070'),
(2, '2025-07-16 05:55:08', '2025-07-16 05:55:08', '4875', '4875', '3', 'Good experience overall. Minimal waiting time, clean hospital environment, and Dr. Sandeep listens patiently. Only issue was a slight delay with reports.', 'Ravindra Malle', 'lakshmihealthin@gmail.com', '9705656070'),
(3, '2025-07-16 05:55:41', '2025-07-16 05:55:41', '4875', '4875', '3', 'Great doctor! He diagnosed my issue quickly and treatment was very effective. The Yashoda Hospital staff were also supportive. Thank you, Dr. Sandeep.', 'Ravindra Malle', 'info@meddylist.com', '9705656070'),
(4, '2025-07-16 05:56:07', '2025-07-16 05:56:07', '4875', '4875', '5', 'One of the best in his specialty. Very attentive and knowledgeable. Follow-up visits were also smooth. Happy with the care received.', 'Ravindra Malle', 'drsandeeptula@gmail.com', '9705656070'),
(5, '2025-07-16 06:04:09', '2025-07-16 06:04:09', '4875', '4875', '2', 'Nice experience with Dr. Sandeep Thul. He was polite and explained every step clearly. Just a little waiting at the hospital due to rush, otherwise everything else was excellent.', 'Ravindra Malle', 'drsandeeptula@gmail.com', '9705656070'),
(6, '2025-07-18 00:07:59', '2025-07-18 00:07:59', '4883', '4883', '4', 'this hosptal so good', 'Ravindra Malle', 'malleravindra0465@gmail.com', '9705656070'),
(7, '2026-06-05 10:26:44', '2026-06-05 10:26:44', '5101', '0', '5', 'Very well treated doctor, best endocrinologist in hyderabad', 'Arun Bhairi', 'arunbhairi669@gmail.com', '08309098626');
INSERT INTO `hospitals_awards_downloads` (`id`, `created_at`, `updated_at`, `user_id`, `awards`, `downloads`) VALUES
(1, '2025-07-18 12:22:16', '2025-07-18 12:22:16', '4883', '[{\"id\":1752840866228,\"title\":\"YASHODA HOSPITALS AWARDED “HOSPITAL WITH HIGHEST STANDARD IN PATIENT CARE” AT CIMS MEDICA HEALTHCARE EXCELLENCE AWARDS 2020\",\"description\":\"Yashoda Hospitals Hyderabad has been awarded the “Hospital with Highest Standard in Patient Care by CIMS Medica Healthcare Excellence Awards 2020. This award is a testament of our commitment to enrich Patient Care.\",\"date\":\"2020-07-05\"},{\"id\":1753072045193,\"title\":\"National Award for Excellence in DNB Programs\",\"description\":\"Yashoda Hospitals was honored as a \\\"Center of Excellence\\\" in DNB Medicine teaching by ANBAI, recognizing its 17-year accreditation by the National Board of Examinations (NBE) and its role in training over 680 DNB graduates in the past 10 years.\",\"date\":\"2017-07-21\"}]', '[{\"id\":1752840876852,\"title\":\"\",\"description\":\"\",\"file\":null,\"file_id\":null}]');
