(12, 'Silver', 'basic', '2999.00', '30', 'INR', '{\"services\": 15, \"brochures\": 3, \"articles\": 5, \"awards\": 5, \"memberships\": 5, \"quickChat\": true, \"bookings\": true, \"featuredProfile\": false, \"featuredDays\": 0, \"duration\": 30, \"socialPosts\": 5, \"socialVideos\": 2, \"autoPost\": false, \"profileWebsite\": false, \"hms\": false}', 'A cost-effective package designed for growing businesses to establish a strong online presence. Includes a single-page website, 3 service posts per month (1 per week), 500 SMS credits, 1000 email credits, AI-generated logo design, and Google Business Profile setup. Ideal for businesses looking to increase visibility and reach more customers online. Domain charges are additional.', 'active', 1, '2025-08-25 05:04:30', '2026-06-05 04:42:34', '2999.00', 'yes', '/uploads/3/packages/1780379266509_images.jpg', 'Silver Growth Package – Essential Digital Presence for Businesses', 'no', 'yes', '500', '0', '1000', '0', '3', '0', '1', 'no', 'yes', '30', '4000.00', 'yes', NULL, NULL, NULL, NULL, NULL, NULL),
(13, 'Gold ', 'business', '3999.00', '30', 'INR', '{\"services\": 30, \"brochures\": 10, \"articles\": 15, \"awards\": 10, \"memberships\": 10, \"quickChat\": true, \"bookings\": true, \"featuredProfile\": true, \"featuredDays\": 100, \"duration\": 30, \"socialPosts\": 30, \"socialVideos\": 10, \"autoPost\": true, \"profileWebsite\": true, \"hms\": true}', 'A premium package designed for businesses and healthcare practices looking to accelerate growth through digital marketing. Includes a 3-page professional website, 6 promotional posts per month (2 per week), 1 AI-generated video every month, lead generation support, 1000 SMS credits, 5000 email credits, 100 WhatsApp marketing messages, AI-generated logo design, and Google Business Profile optimization. Perfect for businesses aiming to increase online visibility, customer engagement, and lead conversions. Domain charges are additional.', 'active', 0, '2025-08-25 05:04:30', '2026-06-05 04:43:10', '4500.00', 'yes', '/uploads/3/packages/1780380507167_images (1).jpg', 'Gold Growth Package – Advanced Digital Marketing & Lead Generation', 'no', 'yes', '1000', '100', '5000', '3', '6', '1', '3', 'no', 'yes', '30', '4500.00', 'yes', NULL, NULL, NULL, NULL, NULL, NULL),
(14, 'Platinum ', 'platinum-', '4999.00', '30', 'INR', NULL, 'Our most comprehensive digital marketing package, designed for businesses and healthcare practices aiming for maximum online visibility, customer engagement, and lead generation. Includes a 6-page professional website, 10 promotional posts per month, automated social media posting across major platforms, AI-powered video marketing, lead generation support, SMS, email, and WhatsApp marketing campaigns, custom logo design, and Google Business Profile optimization. Ideal for businesses seeking a complete digital growth solution. Domain charges are additional', 'active', 0, '2026-06-02 06:37:36', '2026-06-05 04:43:50', '5997', 'yes', '/uploads/3/packages/1780381794513_platinum.png', 'Platinum Premium Package – Complete Digital Growth & Automation Solution', 'yes', 'yes', '2000', '200', '10000', '5', '10', '2', '6', 'yes', 'yes', '30', '5997', 'yes', 'yes', '5126', 'yes', '2', '2', '5126');
