INSERT INTO `professionalwebsite` (`id`, `created_at`, `updated_at`, `title`, `description`, `category`, `status`, `imageUrl`, `imageid`) VALUES
(2, '2025-08-14 09:15:10', '2025-08-14 09:15:10', 'Your Digital Practice, Perfected', 'This design is your modern digital front door,\nengineered to build patient trust with a professional aesthetic.\nIt provides an intuitive experience, making it effortless for visitors to book appointments and recognize your expertise.', 'doctor', 'publish', '/uploads/3/professionalwebsite/1755162866098_doctor1.png', '3210'),
(3, '2025-08-14 09:20:48', '2025-08-14 09:20:48', 'The Compassionate Connection', 'More than a website, this design is a warm, digital handshake.\nIt’s crafted to communicate empathy and reassurance,\ncreating an immediate sense of comfort and connection that puts patients at ease.', 'doctor', 'publish', '/uploads/3/professionalwebsite/1755163245313_doctor2.png', '3212'),
(4, '2025-08-14 09:21:41', '2025-08-14 09:21:41', 'The Collaborative Practice Platform', 'Elevate your group practice into a digital \"Center of Excellence.\"\nThis powerful design showcases the synergy of your entire team, presenting a unified,\nformidable brand while giving each specialist a spotlight.', 'doctor', 'publish', '/uploads/3/professionalwebsite/1755163293664_doctor5.png', '3214'),
(5, '2025-08-14 09:22:32', '2025-08-14 09:22:32', 'Effortless Authority: The Specialist\'s Design', 'In a world of digital noise, clarity is power.\nThis design makes a confident statement through focused simplicity,\ncutting through the clutter to instantly establish your authority and connect you with patients.\n', 'doctor', 'publish', '/uploads/3/professionalwebsite/1755163350206_doctor9.png', '3216'),
(6, '2025-08-14 09:23:34', '2025-08-14 09:23:34', 'The Vanguard: Innovator\'s Showcase', 'Your expertise is cutting-edge; your website should be too.\nThis elite design is a digital showcase for your advanced procedures and innovations,\nreflecting the high level of care you provide and building a reputation for excellence.', 'doctor', 'publish', '/uploads/3/professionalwebsite/1755163412029_doctor10.png', '3218'),
(7, '2025-08-14 09:33:38', '2025-08-14 09:33:38', 'Your Total Healthcare Solution', 'This is your trusted health partner, offering a comprehensive range of services from emergency support to specialized care. With a focus on award-winning patient care and modern technology, we are committed to your well-being.\n\n', 'hospital', 'publish', '/uploads/3/professionalwebsite/1755164017055_hospital1.png', '3220'),
(8, '2025-08-14 09:44:21', '2025-08-14 09:44:21', 'Excellence in Healthcare, Compassion in Practice', 'Experience the pinnacle of medical care where cutting-edge technology meets compassionate service.We provide a comprehensive healthcare experience,ensuring you receive the best treatment in a comfortable and welcoming environment.\n', 'hospital', 'publish', '/uploads/3/professionalwebsite/1755164657287_hospital2.png', '3223'),
(9, '2025-08-14 09:46:32', '2025-08-14 09:46:32', 'A Symphony of Specialized Care', 'Discover a new standard of healthcare where every department works in harmony.From Cardiology to Pediatrics, our specialized centers offer advanced, innovative treatments,ensuring comprehensive and expert care for every patient.\n', 'hospital', 'publish', '/uploads/3/professionalwebsite/1755164787659_hospital4.png', '3225'),
(10, '2025-08-14 09:49:45', '2025-08-14 09:49:45', 'Where Hope and Healing Unite', 'This design embodies a place of hope and healing,\nwhere advanced medical science is delivered with a human touch.\nIt\'s a beacon of trust and a pillar of the community,\ndedicated to providing exceptional care to every patient who walks through our doors.', 'hospital', 'publish', '/uploads/3/professionalwebsite/1755164982380_hospital7.png', '3227'),
(11, '2025-08-14 09:50:59', '2025-08-14 09:50:59', 'HealthVista: A Legacy of Excellence', 'For over 25 years, HealthVista has been a cornerstone of community well-being.\nOur legacy is built on a foundation of expert care, state-of-the-art technology,\nand a commitment to providing high-quality, comprehensive healthcare services.\n', 'hospital', 'publish', '/uploads/3/professionalwebsite/1755165057865_hospital8.png', '3229'),
(12, '2025-08-14 09:53:08', '2025-08-14 09:53:08', 'MeddyCare: The Future of Healthcare', 'Step into the future of healthcare with MeddyCare.\nWe combine world-class medical expertise with the latest technology in a state-of-the-art facility,\nensuring every patient receives the best possible care and a superior healthcare experience.', 'hospital', 'publish', '/uploads/3/professionalwebsite/1755165173350_hospital9.png', '3231'),
(13, '2025-08-14 10:25:21', '2025-08-14 10:25:21', 'Medisat: Pioneering Diagnostic Imaging', 'This is where clarity meets care.\nSpecializing in radiology since 2003,\nthis design showcases cutting-edge imaging services,\noffering physicians and patients unparalleled diagnostic precision and a commitment to excellence.\n', 'laboratory', 'publish', '/uploads/3/professionalwebsite/1755167113660_lab1.png', '3233'),
(14, '2025-08-14 10:26:08', '2025-08-14 10:26:08', 'Biogenix Lab: India\'s Trusted Diagnostic Leader', 'A powerhouse of diagnostic services,\nthis design highlights a vast network and years of experience.\nIt communicates reliability and comprehensive testing capabilities,\npositioning the lab as a cornerstone of national healthcare.', 'laboratory', 'publish', '/uploads/3/professionalwebsite/1755167167756_lab2.png', '3235'),
(15, '2025-08-14 10:26:45', '2025-08-14 10:26:45', 'Laborc: Precision in Chemical & Materials Analysis', 'This design is for the lab that powers industrial and scientific innovation.\nIt emphasizes advanced chemical and metrical analysis, promising clients precise,\nreliable data they can trust for their most critical projects.\n', 'laboratory', 'publish', '/uploads/3/professionalwebsite/1755167204123_lab3.png', '3237'),
(16, '2025-08-14 10:28:08', '2025-08-14 10:28:08', 'MediLab Pro: The Future of Diagnostics, Today', 'Step into the next generation of medical testing.This design showcases AI-powered analysis and rapid results,\noffering personalized health insights that empower patients and physicians with speed and accuracy.', 'laboratory', 'publish', '/uploads/3/professionalwebsite/1755167287190_lab4.png', '3239'),
(17, '2025-08-14 10:28:47', '2025-08-14 10:28:47', 'The Pinnacle of Pathological Insight', 'This design conveys deep expertise and scientific rigor.\nIt is tailored for a leading pathology center, instilling confidence through a focus on detailed analysis,\nexpert interpretation, and a commitment to diagnostic certainty.\n', 'laboratory', 'publish', '/uploads/3/professionalwebsite/1755167326683_lab5.png', '3241'),
(18, '2025-08-14 10:30:33', '2025-08-14 10:30:33', 'MediLab Pro: A Legacy of Diagnostic Excellence', 'Highlighting a rich history since 1998,\nthis design builds on a legacy of trust and quality.\nIt showcases ISO certification and NABL accreditation,\nassuring patients and doctors of the highest standards in medical testing.', 'laboratory', 'publish', '/uploads/3/professionalwebsite/1755167432350_lab6.png', '3243');
