(4581, 'dr_m_sanjeev_kumar', '738e517ee81bfee84d0f5ae6808bd53f2c5e93c14c9610c2097aef19d9b732f0', 'dr_m_sanjeev_kumar', 'm.sanjeev.kumar@example.com', '', '2025-04-25 07:05:29', 'doctor', '', '0', 'Dr M Sanjeev Kumar', '2025-05-03 18:08:13', '2025-05-03 18:08:13', 'Dr M Sanjeev', ' Kumar', '17.4945', '78.3257', NULL, 'doctor', NULL, 'Medicover Hospital, Door No 22, Kalyani Towers, 99, Mumbai Hwy opposite Gandemma Temple, Chanda Nagar, Hyderabad, Telangana 500020', NULL, '4068334455', NULL, NULL, 'male', 'Dr M Sanjeev Kumar - Consultant Neurosurgeon', '700', 'Dr M Sanjeev Kumar is an experienced Consultant Neurosurgeon at Medicover Hospitals in Chandanagar. He has over 11 years of experience and is recognized as one of the best Neurosurgeon. He specializes in brain, spine, nervous system care with advanced treatments that help patients recover quickly and safely.', '[\"English\",\"Hindi\",\"Telugu\"]', '1942', '[]', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[{\"id\":\"neuro_001\",\"name\":\"Brain Surgery\",\"description\":\"Performs surgeries for tumors, trauma, and other brain-related conditions.\"},{\"id\":\"neuro_002\",\"name\":\"Spinal Surgery\",\"description\":\"Expert in treating spinal cord injuries, herniated discs, and deformities.\"},{\"id\":\"neuro_003\",\"name\":\"Minimally Invasive Neurosurgery\",\"description\":\"Specialized in endoscopic and microsurgical techniques for faster recovery.\"}]', NULL, NULL, '1943', '/uploads/3/doctors/banner/1749552569028_logo (8).png', '0', 'Dr_M_Sanjeev_Kumar_Medicover_Hospital', NULL, NULL, NULL, '/uploads/3/doctors/profile/1749552560711_dr-m-sanjeev-kumar.png', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4582, 'dr_sri_anand', '738e517ee81bfee84d0f5ae6808bd53f2c5e93c14c9610c2097aef19d9b732f0', 'dr_sri_anand', 'sri.anand@example.com', '', '2025-04-25 07:10:34', 'doctor', '', '0', ' Dr Anand Karnam', '2025-05-03 18:08:13', '2025-05-03 18:08:13', ' Dr Anand ', 'Karnam', '17.5074', '78.3192', NULL, 'doctor', NULL, 'Plot no 46, first floor, Ameenpur Rd, above Udupi upahar, Reddy Colony, Suraksha Colony, Bandam Kommu, Chanda Nagar, Hyderabad, Telangana 500050', NULL, '4049170420', NULL, NULL, 'male', ' Dr Anand Karnam - Neurologist', '800', 'Dr. Anand is a highly skilled and devoted neurophysician, with an enthusiasm for helping patients overcome neurological challenges. He is committed to advancing the science of neurology and staying at the forefront of research and technology. If you’re looking for a Neurophysician who truly cares about your health and well-being, look no further than Dr. Anand.\n\nHis special interest is in Neuropalliative care, which deals with providing care to Neurological patients with serious illnesses and supporting their caregivers during those difficult times. For a deeper understanding of neuropalliative care, have a conversation with Dr. Anand', '[]', '1946', '[]', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[{\"id\":\"neuro_ped_001\",\"name\":\"Pediatric Neurology\",\"description\":\"Diagnosis and treatment of neurological conditions in children including seizures and developmental disorders.\"},{\"id\":\"gen_med_002\",\"name\":\"General Medicine\",\"description\":\"Comprehensive care for common illnesses and chronic disease management for all age groups.\"},{\"id\":\"ped_care_003\",\"name\":\"Child Wellness\",\"description\":\"Routine checkups, immunizations, and nutritional guidance for children.\"}]', NULL, NULL, '1947', '/uploads/3/doctors/banner/1749553127410_sri-anand-child-and-neuro-center.png', '0', 'Sri_Anand_Child_Neuro_Center_Chanda_Nagar', NULL, NULL, NULL, '/uploads/3/doctors/profile/1749553107492_dr-anand-karnam-neurologist-hyde.png', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4584, 'dr_alluri_neeraja', '738e517ee81bfee84d0f5ae6808bd53f2c5e93c14c9610c2097aef19d9b732f0', 'dr_alluri_neeraja', 'alluri.neeraja@example.com', '', '2025-04-25 07:36:11', 'doctor', '', '0', ' Dr Alluri Neeraja', '2025-05-03 18:08:13', '2025-05-03 18:08:13', ' Dr Alluri ', 'Neeraja', '17.4910', '78.3915', NULL, 'doctor', NULL, 'H.No.261, MIG, Road Number 4, Malaysian Twp, Kukatpally Housing Board Colony, Kukatpally, Hyderabad, Telangana 500072', NULL, '8045680166', NULL, NULL, 'female', ' Dr Alluri Neeraja - Neurologist', '900', 'Dr. Alluri Neeraja is a Neurologist in KPHB, Hyderabad and has an experience of 20 years in this field. Dr. Alluri Neeraja practices at Goutam Neuro Care in KPHB, Hyderabad. She completed DM - Neurology from Gandhi Medical College, Hyderabad in 2018,MBBS from Dr. NTR University of Health Sciences Andhra Pradesh in 2005 and MD - General Medicine from Dr. NTR University of Health Sciences Andhra Pradesh in 2014.', '[\"English\",\"Telugu\"]', '1950', '[]', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[{\"id\":\"neuro_004\",\"name\":\"Parkinson\'s Disease Treatment\",\"description\":\"Comprehensive care for Parkinson\'s disease and movement disorders.\"},{\"id\":\"neuro_005\",\"name\":\"Pediatric Neurology\",\"description\":\"Expert diagnosis and treatment of neurological conditions in children.\"},{\"id\":\"neuro_006\",\"name\":\"Neuro Rehabilitation\",\"description\":\"Therapy and support for patients recovering from neurological illnesses.\"}]', NULL, NULL, '1951', '/uploads/3/doctors/banner/1749553535621_thumbnail (5).png', '0', 'Dr_Alluri_Neeraja_KPHB', NULL, NULL, NULL, '/uploads/3/doctors/profile/1749553526253_images.png', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
