(4588, 'dr_srinivas_gastro', '738e517ee81bfee84d0f5ae6808bd53f2c5e93c14c9610c2097aef19d9b732f0', 'dr_srinivas_gastro', 'srinivas.gastro@example.com', '', '2025-04-25 09:17:19', 'doctor', '', '0', 'Dr G R Srinivas Rao', '2025-05-03 18:08:13', '2025-05-03 18:08:13', 'Dr G R Srinivas ', 'Rao', '17.499762', '78.403215', NULL, 'doctor', NULL, 'MIG-335, Road No. 4, above Bhadra Diagnostics, Kukatpally Housing Board Colony, Kukatpally, Hyderabad, Telangana 500085', NULL, '4045674567', NULL, NULL, 'male', 'Dr G R Srinivas Rao - Senior Consultant Gastroenterologist', '1200', 'Dr. G. R. Srinivas Rao is a Senior Consultant Gastroenterologist at Yashoda Hospitals, Secunderabad, with over 33 years of experience.', '[\"English\",\"Hindi\",\"Kannada\",\"Telugu\",\"Oriya\"]', '1967', '[{\"id\":1749633555554,\"name\":\"Indian Society of Gastroenterology\"},{\"id\":1749633568502,\"name\":\"ISG AP Chapter, Hyderabad\"},{\"id\":1749633590645,\"name\":\"Indian Association for Study of Liver\"},{\"id\":1749633602389,\"name\":\"Indian Society of Enteral and Parental Nutrition\"}]', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"1\":{\"id\":1,\"name\":\"Gastroenterology\",\"description\":\"Treatment of disorders related to the digestive system including the stomach, intestines, and esophagus.\"},\"2\":{\"id\":2,\"name\":\"Hepatology\",\"description\":\"Specialized care for liver diseases such as hepatitis, fatty liver, and cirrhosis.\"},\"3\":{\"id\":3,\"name\":\"Endoscopy\",\"description\":\"Diagnostic and therapeutic procedures using endoscopic techniques for digestive tract issues.\"}}', NULL, NULL, '1968', '/uploads/3/doctors/banner/1749633497385_yashoda-hospitals-logo.png', '1', '', NULL, NULL, NULL, '/uploads/3/doctors/profile/1749633490527_Dr-G.-Srinivas-Rao.png', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4589, 'dr_sunil_pulmonologist', '738e517ee81bfee84d0f5ae6808bd53f2c5e93c14c9610c2097aef19d9b732f0', 'dr_sunil_pulmonologist', 'sunil.lungcare@example.com', '', '2025-04-25 09:19:22', 'doctor', '', '0', 'Dr  S Sunil', '2025-05-03 18:08:13', '2025-05-03 18:08:13', 'Dr  S ', 'Sunil', '17.496543', '78.399876', NULL, 'doctor', NULL, 'MIG 88, 2nd Floor, KPHB Road No.1, KPHB Phase 1, beside Shiv Home World, Kukatpally Housing Board Colony, Kukatpally, Hyderabad, Telangana 500072', NULL, '9347092272', NULL, NULL, 'male', 'Dr  S Sunil – Pulmonologist', '500', ' Dr. S. Sunil, a prominent pulmonologist based in Hyderabad', '[\"English\",\"Telugu\"]', '1971', '[{\"id\":1749634379397,\"name\":\"Medical council of india (MCI)\"},{\"id\":1749637134894,\"name\":\"Member of Indian Chest Society and European Respiratory Society\"}]', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"1\":{\"id\":1,\"name\":\"Pulmonology\",\"description\":\"Specialist in diagnosing and treating respiratory system disorders including asthma, COPD, and lung infections.\"},\"2\":{\"id\":2,\"name\":\"Sleep Medicine\",\"description\":\"Management of sleep-related breathing disorders such as sleep apnea and snoring.\"},\"3\":{\"id\":3,\"name\":\"Allergy and Immunology\",\"description\":\"Treatment of allergic respiratory conditions and immune-related lung issues.\"}}', NULL, NULL, '1972', '/uploads/3/doctors/banner/1749634338995_image (4).png', '1', '', NULL, NULL, NULL, '/uploads/3/doctors/profile/1749634331973_Dr.Sunil_Profile-Photo-1123243-8.png', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4590, 'dr_priyanka_dermatology', '738e517ee81bfee84d0f5ae6808bd53f2c5e93c14c9610c2097aef19d9b732f0', 'dr_priyanka_dermatology', 'priyanka.dermatology@example.com', '', '2025-04-25 09:26:18', 'doctor', '', '0', ' Dr Priyanka Talari', '2025-05-03 18:08:13', '2025-05-03 18:08:13', ' Dr Priyanka ', 'Talari', '17.495678', '78.396782', NULL, 'doctor', NULL, 'First floor, MIG- 323, Road No. 4, above Canara Bank, K P H B Phase 1, Kukatpally, Hyderabad, Telangana 500072', NULL, '630496929', NULL, NULL, 'female', ' Dr. Priyanka Talari – Dermatologist & Cosmetologist', '600', 'Dr. Priyanka Talari is a Dermatologist and Cosmetologist.\n\nDr. Priyanka Talari is an MBBS and earned an MD in DVL (Dermatology, Venereology, and Leprosy) and is Civil Assistant Surgeon at ESI Hospital, R.C Puram. Also, a member in IADVL (Indian Association of Dermatologists, Venereologists, and Leprologists), and AAAM (American Academy of Aesthetic Medicine), Dr. Priyanka’s approach allows for a greater level of clinical expertise in assessing a patient.\n\nWell known in the academic circle, she has presented many papers and case studies, and attends various conferences related to Dermatology & Cosmetology, to keep herself up to date with the latest technology for a minimally invasive approach and to introduce innovative treatments to the patients.', '[\"English\",\"Telugu\"]', '1975', '[{\"id\":1749637500760,\"name\":\"IADVL & American Academy of Aesthetic Medicine (AAAM)\"}]', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"1\":{\"id\":1,\"name\":\"Dermatology\",\"description\":\"Diagnosis and treatment of skin diseases and disorders.\"},\"2\":{\"id\":2,\"name\":\"Cosmetology\",\"description\":\"Advanced cosmetic procedures including acne scar treatment, pigmentation, and anti-aging solutions.\"},\"3\":{\"id\":3,\"name\":\"Hair Treatments\",\"description\":\"Hair loss treatment, PRP therapy, and scalp health solutions.\"}}', NULL, NULL, '1976', '/uploads/3/doctors/banner/1749637470544_AF1QipOfdDlLP6Uf2j71CFBi9SyT2ofc.png', '1', '', NULL, NULL, NULL, '/uploads/3/doctors/profile/1749637462774_AF1QipOmvofl_HNrj770HuNtHxW8qRSB.png', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
