(4599, 'dr_madhurima_naidu', '738e517ee81bfee84d0f5ae6808bd53f2c5e93c14c9610c2097aef19d9b732f0', 'dr_madhurima_naidu', 'dr.madhurima.naidu@example.com', '', '2025-04-25 09:53:27', 'doctor', '', '0', 'Dr Kommisetty Madhurima Naidu ', '2025-05-03 18:08:13', '2025-05-03 18:08:13', 'Dr Kommisetty', ' Madhurima Naidu ', '17.489465', '78.398785', NULL, 'doctor', NULL, 'MIG-144, Rd Number 1, above padmaja hospital, KPHB Phase 2, Kukatpally, Hyderabad, Telangana 500072', NULL, '4048213519', NULL, NULL, 'female', 'Dr. Kommisetty Madhurima Naidu – Orthopaedic Surgeon', '600', 'Dr. Kommisetty Madhurima Naidu is a Orthopedic surgeon in KPHB, Hyderabad and has an experience of 12 years in this field. Dr. Kommisetty Madhurima Naidu practices at Padmaja Hospital in KPHB, Hyderabad. She completed MBBS from Dr. NTR University of Health Sciences Andhra Pradesh in 2013 and MS - Orthopaedics from Dr. NTR University of Health Sciences Andhra Pradesh in 2018.', '[\"English\",\"Telugu\"]', '1991', '[]', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"1\":{\"id\":1,\"name\":\"Orthopedics\",\"description\":\"Treatment for musculoskeletal issues including joint pain, fractures, ligament injuries, and arthritis.\"},\"2\":{\"id\":2,\"name\":\"Joint Replacement\",\"description\":\"Expertise in knee and hip replacement surgeries to restore mobility and reduce chronic pain.\"},\"3\":{\"id\":3,\"name\":\"Sports Injuries\",\"description\":\"Management and surgical care for sports-related injuries to bones, ligaments, and tendons.\"}}', NULL, NULL, '1992', '/uploads/3/doctors/banner/1749641370880_thumbnail (7).png', '0', '', NULL, NULL, NULL, '/uploads/3/doctors/profile/1749641366222_06.png', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
