(4798, 'dr_shipra_sharma', '738e517ee81bfee84d0f5ae6808bd53f2c5e93c14c9610c2097aef19d9b732f0', 'dr_shipra_sharma', 'shipra.sharma@example.com', '', '2025-04-29 05:22:52', 'doctor', '', '0', 'Dr Shipra Sharma', '2025-05-03 18:08:13', '2025-05-03 18:08:13', 'Dr', 'Shipra Sharma', '17.4998', '78.3515', NULL, 'doctor', NULL, 'Sri Balaji Clinic', NULL, '9959606252', NULL, NULL, 'female', ' Dr Shipra Sharma - family physician', '600', 'Dr. Shipra Sharma is a top Family Physician at Sri Balaji Clinic in Hyderabad. Holding MBBS, Dr. Shipra Sharma specializes in diagnosing and treating a wide range of Family Physician conditions, including High Blood Pressure, Diabetes, and more.\n•\nDr. Shipra Sharma has over 18 years of experience and is fluent in English, Hindi, Telugu, Bengali.', '[\"English\",\"Hindi\",\"Bengali\",\"Telugu\"]', '22067', '[{\"id\":1750419916389,\"name\":\"Indian Medical Association (IMA)\"}]', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"GEN001\":{\"name\":\"General Medicine\",\"description\":\"Comprehensive medical care for common illnesses and chronic conditions like diabetes, fever, and hypertension.\"},\"FEV001\":{\"name\":\"Fever Treatment\",\"description\":\"Diagnosis and treatment for various types of fever, including infections and viral conditions.\"},\"DIA001\":{\"name\":\"Diabetes Management\",\"description\":\"Expert care for managing diabetes with a focus on lifestyle changes, medications, and regular monitoring.\"}}', NULL, NULL, '2363', '/uploads/3/doctors/banner/1750419897871_apollo-clinic-logo.png', '1', '', NULL, NULL, NULL, '/uploads/3/doctors/profile/1779368361229_images (3).jfif', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '48', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
