(4805, 'dr_venu_gopal_pareek', '738e517ee81bfee84d0f5ae6808bd53f2c5e93c14c9610c2097aef19d9b732f0', 'dr_venu_gopal_pareek', 'venu.pareek@example.com', '', '2025-04-29 05:52:06', 'doctor', '', '0', 'Dr Venu Gopal Pareek', '2025-05-03 18:08:13', '2025-05-03 18:08:13', 'Dr Venu Gopal ', 'Pareek', '17.4445', '78.4710', NULL, 'doctor', NULL, 'Durga Towers -3 Floor, 1-8-435/436 Rasoolpura, Begumpet, Hyderabad, Telangana 500016', NULL, '4067820170', NULL, NULL, 'male', 'Dr Venu Gopal Pareek - Senior Consultant – GI, Laparoscopic & Bariatric Surgery', '800', 'Dr. Venugopal Pareek trained in prestigious Nizam\'s Institute of medical sciences in field of surgical oncology with Dr. G.S.N Raju of one year\n\nLaparoscopic work includes diagnostic lap, lap Appendix, lap cholecystectomy, PCOD, lap ovarian cystectomies, lap hysterectomy, lap hernia repairs, single port surgeries and open surgeries including colonic and hepatobiliary.\n\nSpecialized interest in bariatric surgeries like sleeve gastrectomy', '[\"English\",\"Hindi\",\"Telugu\",\"Kannada\"]', '22596', '[{\"id\":1750498913919,\"name\":\"FMAS, FIAGES, FAIS\"}]', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[\"88\"]', NULL, NULL, '2380', '/uploads/3/doctors/banner/1750498901350_logo-h4-1.png', '1', 'dr-venu-gopal-pareek-begumpet', NULL, NULL, NULL, '/uploads/3/doctors/profile/1779428673454_download (27).jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '88', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4806, 'dr_niveditha_sai_chandra', '738e517ee81bfee84d0f5ae6808bd53f2c5e93c14c9610c2097aef19d9b732f0', 'dr_niveditha_sai_chandra', 'niveditha.chandra@example.com', '', '2025-04-29 05:56:53', 'doctor', '', '0', 'Dr Niveditha Sai Chandra A ', '2025-05-03 18:08:13', '2025-05-03 18:08:13', 'Dr Niveditha', ' Sai Chandra A ', '17.4375', '78.4602', NULL, 'doctor', NULL, 'KIMS - Sunshine Hospitals, Prakash Nagar, Begumpet, Hyderabad, Telangana 500016', NULL, '8008108108', NULL, NULL, 'female', 'Dr Niveditha Sai Chandra A  - Consultant Neuro‑physician/Neurologist', '800', 'Dr. Sai Chandra Niveditha.A, is an accomplished doctor specializing in Neurology. She has completed her MBBS from Dr. Pinnnamaneni Siddhartha Medical College, Andhra Pradesh and pursued an MD in General Medicine from ASRAM College and a DNB in Neurology from KMCH, Mangalore. She is driven by a passion for treating complex neurological cases. She has also authored five papers in peer-reviewed journals.\n', '[\"English\",\"Kannada\",\"Hindi\",\"Telugu\"]', '22587', '[{\"id\":1750499844000,\"name\":\"Indian Epilepsy Society\"},{\"id\":1750499851259,\"name\":\"Centre for Health and Development (CHD)\"},{\"id\":1750499859977,\"name\":\"AP Doctors Association\"}]', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[\"74\"]', NULL, NULL, '2385', '/uploads/3/doctors/banner/1750499791485_KIMS sunshine1.png', '1', 'dr-niveditha-sai-chandra-begumpet', NULL, NULL, NULL, '/uploads/3/doctors/profile/1779428510196_download (26).jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '74', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4807, 'dr_vimalakar_reddy_eppa', '738e517ee81bfee84d0f5ae6808bd53f2c5e93c14c9610c2097aef19d9b732f0', 'dr_vimalakar_reddy_eppa', 'vimalakar.reddy@example.com', '', '2025-04-29 06:03:50', 'doctor', '', '0', 'Dr  E Vimalakar Reddy', '2025-05-03 18:08:13', '2025-05-03 18:08:13', 'Dr  E Vimalakar ', 'Reddy', '17.4376', '78.4603', NULL, 'doctor', NULL, 'KIMS-SUNSHINE HOSPITALS, Metro Pillar No. C1327 beside Jamia Masjid, Prakash Nagar, Begumpet, Old, opposite Begumpet Airport Road, Hyderabad, Telangana 500016', NULL, '8008108108', NULL, NULL, 'male', 'Dr. E. Vimalakar Reddy (Eppa) - HOD & Senior Consultant Surgical Gastroenterology and Liver Transplantation', '800', 'Dr. E. Vimalakar Reddy is a highly credentialed surgical gastroenterologist with global surgical fellowships and memberships, spearheading complex liver and GI surgeries—especially transplants—at KIMS‑Sunshine Hospitals, Begumpet. His memberships in ASI, IASG, and IHPBA reflect his leadership and clinical excellence in both national and international forums.', '[\"English\",\"Hindi\",\"Telugu\"]', '22578', '[{\"id\":1750500312653,\"name\":\"Association of Surgeons of India (ASI)\"},{\"id\":1750500319853,\"name\":\"Indian Association of Surgical Gastroenterology (IASG)\"},{\"id\":1750500326480,\"name\":\"International Hepato-Pancreato-Biliary Association (IHPBA)\"}]', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[\"45\"]', NULL, NULL, '2389', '/uploads/3/doctors/banner/1750500299110_kims_logo.dd3a9a1 (1).png', '0', 'dr-vimalakar-reddy-eppa-begumpet', NULL, NULL, NULL, '/uploads/3/doctors/profile/1779428331692_download (25).jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '45', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4808, 'dr_chandrashekar_b', '738e517ee81bfee84d0f5ae6808bd53f2c5e93c14c9610c2097aef19d9b732f0', 'dr_chandrashekar_b', 'chandrashekar.b@example.com', '', '2025-04-29 06:11:25', 'doctor', '', '0', 'Dr B Chandra Sekhar', '2025-05-03 18:08:13', '2025-05-03 18:08:13', 'Dr B Chandra ', 'Sekhar', '17.4376', '78.4603', NULL, 'doctor', NULL, 'KIMS - Sunshine Hospitals, Prakash Nagar, Begumpet, Hyderabad, Telangana 500016', NULL, '40555000', NULL, NULL, 'male', 'Dr B Chandra Sekhar - Consultant Shoulder & Arthroscopy Surgeon', '500', 'Dr. B. Chandrasekhar has been in the field of Orthopaedics & Shoulder Surgery for over a decade and during this period he has accumulated immense experience and expertise in arthroscopic shoulder surgery, advanced open reconstructive surgery of shoulder and shoulder joint replacement surgery.\n\nDr. B. Chandrasekhar leads a team of highly experienced specialists dedicated to manage the exclusive Shoulder care program and ranked among top-rated surgeons in India to perform both shoulder replacement surgery and shoulder arthroscopy.', '[\"English\",\"Telugu\",\"Hindi\"]', '22568', '[{\"id\":1750502167678,\"name\":\"Indian Arthroscopy Society\"},{\"id\":1750502174062,\"name\":\"Shoulder & Elbow Society of India\"}]', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[\"96\"]', NULL, NULL, '2393', '/uploads/3/doctors/banner/1750501740061_KIMS sunshine1.png', '1', 'dr-chandrashekar-b-orthopedic-begumpet', NULL, NULL, NULL, '/uploads/3/doctors/profile/1779428121603_download (24).jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '96', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4809, 'dr_g_parthasarathy', '738e517ee81bfee84d0f5ae6808bd53f2c5e93c14c9610c2097aef19d9b732f0', 'dr_g_parthasarathy', 'g.parthasarathy@example.com', '', '2025-04-29 06:20:53', 'doctor', '', '0', 'Dr G Parthasarathy ', '2025-05-03 18:08:13', '2025-05-03 18:08:13', 'Dr G ', 'Parthasarathy ', '17.4401', '78.4735', NULL, 'doctor', NULL, '31, KIMS Hospitals, 1-8, 1, Minister Rd, Krishna Nagar Colony, Begumpet, Hyderabad, Telangana 500003', NULL, '4044885000', NULL, NULL, 'male', 'Dr G Parthasarathy - Senior Consultant in Surgical Gastroenterology, Laparoscopic, and Hepato‑Pancreato‑Biliary Surgery', '1000', 'Dr. G. Parthasarathy is a senior consultant in the department of surgical gastroenterology and minimal access surgery at the renowned KIMS Hospitals, Secunderabad. He has an illustrious academic and professional record spanning two decades. He completed his undergraduate and postgraduate medical training from JIPMER. He spent three years as a faculty of surgery, training postgraduates. He later went on to earn his super specialty degree in surgical gastroenterology from the prestigious SGPGIMS, Lucknow. After this, he trained in advanced hepatobiliary surgery and liver transplantation from CLBS, New Delhi. To further hone his skills he went as an international visiting fellow to Asan medical center, Seoul, S.Korea.He was awarded the Fellowship by the Indian Association of gastroendoscopic surgeons (FIAGES) in 2016.', '[\"English\",\"Hindi\",\"Telugu\"]', '22556', '[{\"id\":1750503150658,\"name\":\"Indian Association of Surgical Gastroenterologists (IASG)\"},{\"id\":1750503157926,\"name\":\"Indian Association of Gastro-Endo-Surgeons (IAGES) – Fellow (FIAGES)\"}]', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[\"131\"]', NULL, NULL, '2397', '/uploads/3/doctors/banner/1750503136441_kims_logo.dd3a9a1 (1).png', '1', 'dr-g-parthasarathy-kims-begumpet', NULL, NULL, NULL, '/uploads/3/doctors/profile/1779427851557_download (23).jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '131', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4810, 'dr_fini_ani_philip', '738e517ee81bfee84d0f5ae6808bd53f2c5e93c14c9610c2097aef19d9b732f0', 'dr_fini_ani_philip', 'dr.fini@example.com', '', '2025-04-29 06:25:49', 'doctor', '', '0', 'Dr Fini Ani Philip', '2025-05-03 18:08:13', '2025-05-03 18:08:13', 'Dr Fini Ani ', 'Philip', '17.4933', '78.3915', NULL, 'doctor', NULL, 'Shop No. 5, Raja Roja Nilayam, Gokul Plots, KPHB Phase-9, Kukatpally, Hyderabad, Telangana 500085', NULL, '9885000720', NULL, NULL, 'female', 'Dr Fini Ani Philip - general physician and geriatric specialist ', '500', 'Dr. Fini philip has over 20 years of experience as a general medical practitioner. She has accumulated a wealth of experience in the diagnosis and treatment of general medical diseases and aliments. She is also a specialist in geriatric medicine and can manage all old age related health problems.', '[\"English\",\"Hindi\",\"Telugu\"]', '22544', '[]', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[null,\"30\"]', NULL, NULL, '2401', '/uploads/3/doctors/banner/1750503883331_AF1QipOvzpTJGYuCJKj1fLCigp4TbzGw.png', '0', '', NULL, NULL, NULL, '/uploads/3/doctors/profile/1779427567892_ChatGPT Image May 22, 2026, 10_55_54 AM.png', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4811, 'dr_chetan_homeo', '738e517ee81bfee84d0f5ae6808bd53f2c5e93c14c9610c2097aef19d9b732f0', 'dr_chetan_homeo', 'chetan.homeo@example.com', '', '2025-04-29 06:35:25', 'doctor', '', '0', ' Dr Chetan Raj', '2025-05-03 18:08:13', '2025-05-03 18:08:13', ' Dr Chetan ', 'Raj', '17.4442', '78.4603', NULL, 'doctor', NULL, 'Flat No 101, Shyamlal Buildings, Kura Mansion, Begumpet, Hyderabad, Telangana 500016', NULL, '9032037037', NULL, NULL, 'male', ' Dr Chetan Raj - BHMS, MS - Counselling & Psychotherapy  AYUSH Homoeopath,Sexologist,Counselling Psychologist', '999', 'Dr. Chetan Raj has been a successful Homeopath ever since the beginning. Dr. Chetan started his career as a consultant homeopath by setting up his own clinic, Dr. Chetan’S Homeo Clinic In Narayanaguda, Hyderabad with the motto ‘Service To Humanity’. Dr. Chetan Raj completed his B.H.M.S. from Rajiv Gandhi University Of Health Sciences, Gulbarga, C.C.H (Pediatrics), S.V.D from Jankalyan Institute Of Health Sciences and M.S. (Psychotherapy) from Kuvempu University, Shimoga.', '[\"English\",\"Telugu\",\"Hindi\"]', '22532', '[]', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[\"57\"]', NULL, NULL, '2407', '/uploads/3/doctors/banner/1750504617163_dr-chetan-raj-dr-chetan-s-homeo.png', '0', 'dr-chetan-homeo-begumpet', NULL, NULL, NULL, '/uploads/3/doctors/profile/1779427291795_ChatGPT Image May 22, 2026, 10_51_17 AM.png', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '57', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
